    // land on the same clip position so the triangles are degenerate.
    vCol = vec4(0.0);
    vUv = vec2(0.0);
    vKind = 0.0;
    vU = 0.0;
    vDepth = 1.0;
    vSize = 0.0;
    vSeed = 0.0;
